addons-autoplay--autoplay.snippet:
import { Component } from '@angular/core';
import { GalleryAutoplay } from 'ng-gallery';
import { GalleryModule } from 'ng-gallery';

@Component({
  selector: 'app-demo',
  imports: [GalleryAutoplay, GalleryModule],
  template: `
    <gallery
        loop
        [items]="items"
        [autoplay]="autoplay"
        [autoplayInterval]="autoplayInterval"
        [autoplayScrollBehavior]="autoplayScrollBehavior"
        [autoplayDirection]="autoplayDirection"
        [autoplayPause]="autoplayPause"
        (autoplayChange)="autoplayChange($event)">
        <img
            *galleryItemDef="let item"
            galleryImage
            [src]="item.src"
            [alt]="item.alt" />
        @if (showSpinner) {
        <gallery-autoplay
            gallerySlot
            gallerySlotJustify="end"
            gallerySlotAlign="start" />
        }
            @if (showProgressbar) {
        <gallery-autoplay gallerySlot gallerySlotAlign="end" mode="progressbar"/>
        }
    </gallery>`,
})
export class DemoComponent {
  autoplay = true;
  autoplayInterval = 3000;
  autoplayScrollBehavior = 'smooth';
  autoplayDirection = 'forward';
  autoplayPause = 'hover';
  showSpinner = true;
  showProgressbar = true;
  autoplayChange(event: unknown) {}
}
